#!/usr/bin/env node
import { readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
const REPO_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const PRODUCT_PACKAGE = "packages/cli/package.json";
function productHome(repoRoot = REPO_ROOT) {
    const manifest = JSON.parse(readFileSync(join(repoRoot, PRODUCT_PACKAGE), "utf8"));
    return "string" == typeof manifest.homepage && "" !== manifest.homepage ? manifest.homepage : null;
}
const PRODUCT_HOME_SOURCE = PRODUCT_PACKAGE;
export { PRODUCT_HOME_SOURCE, productHome };
